#!/usr/bin/env python3
"""Filter name-sorted SAM to complete, valid paired-end records."""

import sys

MITO_NAMES = {"chrM", "MT", "M", "chrMT"}


def parse_flag(record):
    return int(record.split("\t", 3)[1])


def record_passes(record):
    fields = record.rstrip("\n").split("\t")
    if len(fields) < 11:
        return False
    flag = int(fields[1])
    mapq = int(fields[4])
    rname = fields[2]
    rnext = fields[6]
    disallowed = 0x4 | 0x8 | 0x100 | 0x200 | 0x800
    if flag & disallowed:
        return False
    if not (flag & 0x2):
        return False
    if mapq < 30:
        return False
    if rname in MITO_NAMES:
        return False
    if rnext != "=" and rnext in MITO_NAMES:
        return False
    return True


def emit_if_complete(records):
    passing = [record for record in records if record_passes(record)]
    if len(passing) != 2:
        return
    flags = [parse_flag(record) for record in passing]
    if not any(flag & 0x40 for flag in flags):
        return
    if not any(flag & 0x80 for flag in flags):
        return
    for record in passing:
        sys.stdout.write(record)


current_name = None
current_records = []

for line in sys.stdin:
    if line.startswith("@"):
        sys.stdout.write(line)
        continue
    qname = line.split("\t", 1)[0]
    if current_name is None:
        current_name = qname
    if qname != current_name:
        emit_if_complete(current_records)
        current_name = qname
        current_records = []
    current_records.append(line)

if current_records:
    emit_if_complete(current_records)

